const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;e.target.classList.add('vis');
 e.target.querySelectorAll('[data-n]').forEach(b=>{const n=+b.dataset.n,s=b.dataset.s||'';let t0;const f=t=>{t0??=t;const p=Math.min(1,(t-t0)/1300);b.textContent=Math.round(n*(1-Math.pow(1-p,3)))+s;if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)});io.unobserve(e.target)}),{threshold:.1,rootMargin:'0px 0px -40px 0px'});
window.NXreveal=()=>$$('.rv:not(.vis)').forEach(el=>io.observe(el));

