/* ---------- WhatsApp hand-off: real link + copy fallback (works in apps, iframes and previews) ---------- */
window.NXwa=function(text,box){
 const url='https://wa.me/'+N.WA+'?text='+encodeURIComponent(text);
 const inFrame=(()=>{try{return window.top!==window.self}catch(e){return true}})();
 if(box){box.className='wa-ready';box.innerHTML=`<span class="wa-t">${ic('check-circle')}Your message is ready</span>
  <a class="btn wa" href="${url}" target="_blank" rel="noopener noreferrer">${ic('chat')}Open WhatsApp &amp; send</a>
  <span class="wa-alt">Or WhatsApp us at <b>+${N.WA.replace(/^91/,'91 ').replace(/(\d{5})(\d{5})$/,'$1 $2')}</b> · <button type="button" class="wa-copy">Copy message</button></span>`;
  const cp=box.querySelector('.wa-copy');cp.addEventListener('click',()=>{const done=()=>{cp.textContent='Copied'};
   (navigator.clipboard?navigator.clipboard.writeText(text):Promise.reject()).then(done).catch(()=>{const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();try{document.execCommand('copy');done()}catch(e){}t.remove()})});}
 if(!inFrame){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove()}
 return url};

/* ---------- Sign in ---------- */
function ensureSignin(){if($('#signin'))return;
 const mark=($('.nav .brand .mk img')||{}).src||'',art=($('.hx-sym img')||$('.nav .brand .mk img')||{}).src||'';
 document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="signin" role="dialog" aria-modal="true" aria-labelledby="siT"><div class="sibox">
 <div class="si-art"><img src="${art}" alt=""><div class="si-art-tx"><span class="eyebrow">Nexobova workspace</span><h3>Your business, one sign-in away.</h3><ul><li>${ic('check-circle')}CRM, billing, WhatsApp and AI agents in one place</li><li>${ic('check-circle')}Role-based access for every team member</li><li>${ic('check-circle')}Your data stays yours</li></ul></div></div>
 <form class="si-form" id="siForm" novalidate>
  <button type="button" class="dx si-x" aria-label="Close">${ic('x')}</button>
  <div class="brand"><span class="mk"><img src="${mark}" alt="" width="36" height="36"></span><span class="wm">nexobova</span></div>
  <h2 id="siT">Sign in</h2><p class="si-sub">Access your Nexobova client workspace.</p>
  <label for="siEmail">Work email</label><input id="siEmail" type="email" autocomplete="email" placeholder="you@company.com" required>
  <label for="siOrg">Company / workspace</label><input id="siOrg" autocomplete="organization" placeholder="e.g. Veltrix Engineering">
  <button class="btn pri" type="submit">${ic('lock')}Request secure sign-in link</button>
  <div class="or"><span>or</span></div>
  <a class="btn" id="siMail" href="mailto:${N.EMAIL}?subject=${encodeURIComponent('Nexobova workspace sign-in')}">${ic('mail')}Email ${N.EMAIL}</a>
  <p class="si-msg" id="siMsg" role="status"></p>
  <p class="si-note">${ic('shield')}<span>For your security, workspace sign-in links are issued and verified by the Nexobova team on WhatsApp during working hours.</span></p>
  <p class="si-new">New to Nexobova? <a href="#" data-demo>Book a free demo</a></p>
 </form></div></div>`);
 const ov=$('#signin');
 ov.addEventListener('click',e=>{if(e.target===ov||e.target.closest('.si-x'))closeSignin()});
 $('#siForm').addEventListener('submit',e=>{e.preventDefault();const em=$('#siEmail'),msg=$('#siMsg');
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em.value.trim())){msg.className='si-msg err';msg.textContent='Enter the work email your Nexobova account uses, for example you@company.com.';em.focus();return}
  const txt=`Hello Nexobova,\n\nPlease send me a secure sign-in link for my workspace.\n\nEmail: ${em.value.trim()}\nWorkspace: ${$('#siOrg').value.trim()||'Not provided'}`;
  msg.className='si-msg';NXwa(txt,msg)})}
function openSignin(){ensureSignin();closeDD();closeMenu();$('#signin').classList.add('open');document.body.style.overflow='hidden';setTimeout(()=>$('#siEmail').focus(),60)}
function closeSignin(){const s=$('#signin');if(s&&s.classList.contains('open')){s.classList.remove('open');document.body.style.overflow=''}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-signin]');if(!a)return;e.preventDefault();openSignin()},true);
addEventListener('keydown',e=>{if(e.key==='Escape')closeSignin()});

